  1| package org.jsoup.nodes;
  2| 
  3| import org.jsoup.helper.Validate;
  4| import org.jsoup.parser.Tag;
  5| import org.jsoup.select.Elements;
  6| 
  7| import java.nio.charset.Charset;
  8| import java.nio.charset.CharsetEncoder;
  9| import java.util.ArrayList;
 10| import java.util.List;
 11| 
 12| /**
 13|  A HTML Document.
 14| 
 15|  @author Jonathan Hedley, jonathan@hedley.net */
 16| public class Document extends Element {
 17|     private OutputSettings outputSettings = new OutputSettings();
 18|     private QuirksMode quirksMode = QuirksMode.noQuirks;
 19| 
 20|     /**
 21|      Create a new, empty Document.
 22|      @param baseUri base URI of document
 23|      @see org.jsoup.Jsoup#parse
 24|      @see #createShell
 25|      */
 26|     public Document(String baseUri) {
 27|         super(Tag.valueOf("#root"), baseUri);
 28|     }
 29| 
 30|     /**
 31|      Create a valid, empty shell of a document, suitable for adding more elements to.
 32|      @param baseUri baseUri of document
 33|      @return document with html, head, and body elements.
 34|      */
 35|     static public Document createShell(String baseUri) {
 36|         Validate.notNull(baseUri);
 37| 
 38|         Document doc = new Document(baseUri);
 39|         Element html = doc.appendElement("html");
 40|         html.appendElement("head");
 41|         html.appendElement("body");
 42| 
 43|         return doc;
 44|     }
 45| 
 46|     /**
 47|      Accessor to the document's {@code head} element.
 48|      @return {@code head}
 49|      */
 50|     public Element head() {
 51|         return findFirstElementByTagName("head", this);
 52|     }
 53| 
 54|     /**
 55|      Accessor to the document's {@code body} element.
 56|      @return {@code body}
 57|      */
 58|     public Element body() {
 59|         return findFirstElementByTagName("body", this);
 60|     }
 61| 
 62|     /**
 63|      Get the string contents of the document's {@code title} element.
 64|      @return Trimmed title, or empty string if none set.
 65|      */
 66|     public String title() {
 67|         // title is a preserve whitespace tag (for document output), but normalised here
 68|         Element titleEl = getElementsByTag("title").first();
 69|         return titleEl != null ? titleEl.text().trim() : "";
 70|     }
 71| 
 72|     /**
 73|      Set the document's {@code title} element. Updates the existing element, or adds {@code title} to {@code head} if
 74|      not present
 75|      @param title string to set as title
 76|      */
 77|     public void title(String title) {
 78|         Validate.notNull(title);
 79|         Element titleEl = getElementsByTag("title").first();
 80|         if (titleEl == null) { // add to head
 81|             head().appendElement("title").text(title);
 82|         } else {
 83|             titleEl.text(title);
 84|         }
 85|     }
 86| 
 87|     /**
 88|      Create a new Element, with this document's base uri. Does not make the new element a child of this document.
 89|      @param tagName element tag name (e.g. {@code a})
 90|      @return new element
 91|      */
 92|     public Element createElement(String tagName) {
 93|         return new Element(Tag.valueOf(tagName), this.baseUri());
 94|     }
 95| 
 96|     /**
 97|      Normalise the document. This happens after the parse phase so generally does not need to be called.
 98|      Moves any text content that is not in the body element into the body.
 99|      @return this document after normalisation
100|      */
101|     public Document normalise() {
102|         Element htmlEl = findFirstElementByTagName("html", this);
103|         if (htmlEl == null)
104|             htmlEl = appendElement("html");
105|         if (head() == null)
106|             htmlEl.prependElement("head");
107|         if (body() == null)
108|             htmlEl.appendElement("body");
109| 
110|         // pull text nodes out of root, html, and head els, and push into body. non-text nodes are already taken care
111|         // of. do in inverse order to maintain text order.
112|         normaliseTextNodes(head());
113|         normaliseTextNodes(htmlEl);
114|         normaliseTextNodes(this);
115| 
116|         normaliseStructure("head", htmlEl);
117|         normaliseStructure("body", htmlEl);
118|         
119|         return this;
120|     }
121| 
122|     // does not recurse.
123|     private void normaliseTextNodes(Element element) {
124|         List<Node> toMove = new ArrayList<Node>();
125|         for (Node node: element.childNodes) {
126|             if (node instanceof TextNode) {
127|                 TextNode tn = (TextNode) node;
128|                 if (!tn.isBlank())
129|                     toMove.add(tn);
130|             }
131|         }
132| 
133|         for (int i = toMove.size()-1; i >= 0; i--) {
134|             Node node = toMove.get(i);
135|             element.removeChild(node);
136|             body().prependChild(new TextNode(" ", ""));
137|             body().prependChild(node);
138|         }
139|     }
140| 
141|     // merge multiple <head> or <body> contents into one, delete the remainder, and ensure they are owned by <html>
142|     private void normaliseStructure(String tag, Element htmlEl) {
143|         Elements elements = this.getElementsByTag(tag);
144|         Element master = elements.first(); // will always be available as created above if not existent
145|         if (elements.size() > 1) { // dupes, move contents to master
146|             List<Node> toMove = new ArrayList<Node>();
147|             for (int i = 1; i < elements.size(); i++) {
148|                 Node dupe = elements.get(i);
149|                 for (Node node : dupe.childNodes)
150|                     toMove.add(node);
151|                 dupe.remove();
152|             }
153| 
154|             for (Node dupe : toMove)
155|                 master.appendChild(dupe);
156|         }
157|         // ensure parented by <html>
158|         if (!master.parent().equals(htmlEl)) {
159|             htmlEl.appendChild(master); // includes remove()            
160|         }
161|     }
162| 
163|     // fast method to get first by tag name, used for html, head, body finders
164|     private Element findFirstElementByTagName(String tag, Node node) {
165|         if (node.nodeName().equals(tag))
166|             return (Element) node;
167|         else {
168|             for (Node child: node.childNodes) {
169|                 Element found = findFirstElementByTagName(tag, child);
170|                 if (found != null)
171|                     return found;
172|             }
173|         }
174|         return null;
175|     }
176| 
177|     @Override
178|     public String outerHtml() {
179|         return super.html(); // no outer wrapper tag
180|     }
181| 
182|     /**
183|      Set the text of the {@code body} of this document. Any existing nodes within the body will be cleared.
184|      @param text unencoded text
185|      @return this document
186|      */
187|     @Override
188|     public Element text(String text) {
189|         body().text(text); // overridden to not nuke doc structure
190|         return this;
191|     }
192| 
193|     @Override
194|     public String nodeName() {
195|         return "#document";
196|     }
197| 
198|     @Override
199|     public Document clone() {
200|         Document clone = (Document) super.clone();
201|         clone.outputSettings = this.outputSettings.clone();

